import{_ as l,a0 as r,w as p,s as o,I as e,x as n,a1 as s,A as i,ao as c}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"Rancher：一个全面的可用于产品环境的容器管理平台 | LCTT x X-CMD","titleTemplate":false,"description":"Rancher：一个全面的可用于产品环境的容器管理平台 | LCTT (201904) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Rancher：一个全面的可用于产品环境的容器管理平台 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Rancher：一个全面的可用于产品环境的容器管理平台 | LCTT (201904) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201904/20180205 Rancher - Container Management Application","title":"Rancher：一个全面的可用于产品环境的容器管理平台","tag":"201904","desc":""},"relativePath":"201904/20180205 Rancher - Container Management Application.md","filePath":"[post].md"}'),d={name:"201904/20180205 Rancher - Container Management Application.md"};function h(g,a,u,m,k,w){const t=r("Link");return p(),o("div",null,[a[22]||(a[22]=e("h1",{id:"rancher-一个全面的可用于产品环境的容器管理平台",tabindex:"-1"},[n("Rancher：一个全面的可用于产品环境的容器管理平台 "),e("a",{class:"header-anchor",href:"#rancher-一个全面的可用于产品环境的容器管理平台","aria-label":"Permalink to “Rancher：一个全面的可用于产品环境的容器管理平台”"},"​")],-1)),a[23]||(a[23]=e("p",null,"Docker 作为一款容器化应用的新兴软件，被大多数 IT 公司使用来减少基础设施平台的成本。",-1)),a[24]||(a[24]=e("p",null,"通常，没有 GUI 的 Docker 软件对于 Linux 管理员来说很容易，但是对于开发者来就有点困难。当把它搬到生产环境上来，那么它对 Linux 管理员来说也相当不友好。那么，轻松管理 Docker 的最佳解决方案是什么呢？",-1)),a[25]||(a[25]=e("p",null,"唯一的办法就是提供 GUI。Docker API 允许第三方应用接入 Docker。在市场上有许多 Docker GUI 应用。我们已经写过一篇关于 Portainer 应用的文章。今天我们来讨论另一个应用，Rancher。",-1)),a[26]||(a[26]=e("p",null,"容器让软件开发更容易，让开发者更快的写代码、更好的运行它们。但是，在生产环境上运行容器却很困难。",-1)),e("p",null,[a[1]||(a[1]=e("strong",null,"推荐阅读：",-1)),a[2]||(a[2]=n()),s(t,{href:"https://www.2daygeek.com/portainer-a-simple-docker-management-gui/"},{default:i(()=>[...a[0]||(a[0]=[n("Portainer：一个简单的 Docker 管理图形工具",-1)])]),_:1})]),a[27]||(a[27]=e("h3",{id:"rancher-简介",tabindex:"-1"},[n("Rancher 简介 "),e("a",{class:"header-anchor",href:"#rancher-简介","aria-label":"Permalink to “Rancher 简介”"},"​")],-1)),e("p",null,[s(t,{href:"http://rancher.com/"},{default:i(()=>[...a[3]||(a[3]=[n("Rancher",-1)])]),_:1}),a[4]||(a[4]=n(" 是一个全面的容器管理平台，它可以让容器在各种基础设施平台的生产环境上部署和运行更容易。它提供了诸如多主机网络、全局/本地负载均衡和卷快照等基础设施服务。它整合了原生 Docker 的管理能力，如 Docker Machine 和 Docker Swarm。它提供了丰富的用户体验，让 DevOps 管理员在更大规模的生产环境上运行 Docker。",-1))]),a[28]||(a[28]=e("p",null,"访问以下文章可以了解 Linux 系统上安装 Docker。",-1)),a[29]||(a[29]=e("p",null,[e("strong",null,"推荐阅读：")],-1)),e("ul",null,[e("li",null,[s(t,{href:"https://www.2daygeek.com/install-docker-on-centos-rhel-fedora-ubuntu-debian-oracle-archi-scentific-linux-mint-opensuse/"},{default:i(()=>[...a[5]||(a[5]=[n("如何在 Linux 上安装 Docker",-1)])]),_:1})]),e("li",null,[s(t,{href:"https://www.2daygeek.com/list-search-pull-download-remove-docker-images-on-linux/"},{default:i(()=>[...a[6]||(a[6]=[n("如何在 Linux 上使用 Docker 镜像",-1)])]),_:1})]),e("li",null,[s(t,{href:"https://www.2daygeek.com/create-run-list-start-stop-attach-delete-interactive-daemonized-docker-containers-on-linux/"},{default:i(()=>[...a[7]||(a[7]=[n("如何在 Linux 上使用 Docker 容器",-1)])]),_:1})]),e("li",null,[s(t,{href:"https://www.2daygeek.com/install-run-applications-inside-docker-containers/"},{default:i(()=>[...a[8]||(a[8]=[n("如何在 Docker 容器内安装和运行应用",-1)])]),_:1})])]),a[30]||(a[30]=c(`<h3 id="rancher-特性" tabindex="-1">Rancher 特性 <a class="header-anchor" href="#rancher-特性" aria-label="Permalink to “Rancher 特性”">​</a></h3><ul><li>可以在两分钟内安装 Kubernetes。</li><li>一键启动应用（90 个流行的 Docker 应用）。</li><li>部署和管理 Docker 更容易。</li><li>全面的生产级容器管理平台。</li><li>可以在生产环境上快速部署容器。</li><li>强大的自动部署和运营容器技术。</li><li>模块化基础设施服务。</li><li>丰富的编排工具。</li><li>Rancher 支持多种认证机制。</li></ul><h3 id="怎样安装-rancher" tabindex="-1">怎样安装 Rancher <a class="header-anchor" href="#怎样安装-rancher" aria-label="Permalink to “怎样安装 Rancher”">​</a></h3><p>由于 Rancher 是以轻量级的 Docker 容器方式运行，所以它的安装非常简单。Rancher 是由一组 Docker 容器部署的。只需要简单的启动两个容器就能运行 Rancher。一个容器用作管理服务器，另一个容器在各个节点上作为代理。在 Linux 系统下简单的运行下列命令就能部署 Rancher。</p><p>Rancher 服务器提供了两个不同的安装包标签如 <code>stable</code> 和 <code>latest</code>。下列命令将会拉取适合的 Rancher 镜像并安装到你的操作系统上。Rancher 服务器仅需要两分钟就可以启动。</p><ul><li><code>latest</code>：这个标签是他们的最新开发构建。这些构建将通过 Rancher CI 的自动化框架进行验证，不建议在生产环境使用。</li><li><code>stable</code>：这是最新的稳定发行版本，推荐在生产环境使用。</li></ul><p>Rancher 的安装方法有多种。在这篇教程中我们仅讨论两种方法。</p><ul><li>以单一容器的方式安装 Rancher（内嵌 Rancher 数据库）</li><li>以单一容器的方式安装 Rancher（外部数据库）</li></ul><h3 id="方法-1" tabindex="-1">方法 - 1 <a class="header-anchor" href="#方法-1" aria-label="Permalink to “方法 - 1”">​</a></h3><p>运行下列命令以单一容器的方式安装 Rancher 服务器（内嵌数据库）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run -d --restart=unless-stopped -p 8080:8080 rancher/server:stable</span></span>
<span class="line"><span>$ sudo docker run -d --restart=unless-stopped -p 8080:8080 rancher/server:latest</span></span></code></pre></div><h3 id="方法-2" tabindex="-1">方法 - 2 <a class="header-anchor" href="#方法-2" aria-label="Permalink to “方法 - 2”">​</a></h3><p>你可以在启动 Rancher 服务器时指向外部数据库，而不是使用自带的内部数据库。首先创建所需的数据库，数据库用户为同一个。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; CREATE DATABASE IF NOT EXISTS cattle COLLATE = &#39;utf8_general_ci&#39; CHARACTER SET = &#39;utf8&#39;;</span></span>
<span class="line"><span>&gt; GRANT ALL ON cattle.* TO &#39;cattle&#39;@&#39;%&#39; IDENTIFIED BY &#39;cattle&#39;;</span></span>
<span class="line"><span>&gt; GRANT ALL ON cattle.* TO &#39;cattle&#39;@&#39;localhost&#39; IDENTIFIED BY &#39;cattle&#39;;</span></span></code></pre></div><p>运行下列命令启动 Rancher 去连接外部数据库。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run -d --restart=unless-stopped -p 8080:8080 rancher/server \\</span></span>
<span class="line"><span> --db-host myhost.example.com --db-port 3306 --db-user username --db-pass password --db-name cattle</span></span></code></pre></div><p>如果你想测试 Rancher 2.0，使用下列的命令去启动。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run -d --restart=unless-stopped -p 80:80 -p 443:443 rancher/server:preview</span></span></code></pre></div><h3 id="通过-gui-访问-安装-rancher" tabindex="-1">通过 GUI 访问 &amp; 安装 Rancher <a class="header-anchor" href="#通过-gui-访问-安装-rancher" aria-label="Permalink to “通过 GUI 访问 &amp; 安装 Rancher”">​</a></h3><p>浏览器输入 <code>http://hostname:8080</code> 或 <code>http://server_ip:8080</code> 去访问 rancher GUI.</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-1.png" alt=""></p><h3 id="怎样注册主机" tabindex="-1">怎样注册主机 <a class="header-anchor" href="#怎样注册主机" aria-label="Permalink to “怎样注册主机”">​</a></h3><p>注册你的主机 URL 允许它连接到 Rancher API。这是一次性设置。</p><p>接下来，点击主菜单下面的 “Add a Host” 链接或者点击主菜单上的 “INFRASTRUCTURE &gt;&gt; Add Hosts”，点击 “Save” 按钮。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-2.png" alt=""></p><p>默认情况下，Rancher 里的访问控制认证禁止了访问，因此我们首先需要通过一些方法打开访问控制认证，否则任何人都不能访问 GUI。</p><p>点击 “&gt;&gt; Admin &gt;&gt; Access Control”，输入下列的值最后点击 “Enable Authentication” 按钮去打开它。在我这里，是通过 “local authentication” 的方式打开的。</p><ul><li>“Login UserName”： 输入你期望的登录名</li><li>“Full Name”： 输入你的全名</li><li>“Password”： 输入你期望的密码</li><li>“Confirm Password”： 再一次确认密码</li></ul><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-3.png" alt=""></p><p>注销然后使用新的登录凭证重新登录：</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-3a.png" alt=""></p><p>现在，我能看到本地认证已经被打开。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-4.png" alt=""></p><h3 id="怎样添加主机" tabindex="-1">怎样添加主机 <a class="header-anchor" href="#怎样添加主机" aria-label="Permalink to “怎样添加主机”">​</a></h3><p>注册你的主机后，它将带你进入下一个页面，在那里你能选择不同云服务提供商的 Linux 主机。我们将添加一个主机运行 Rancher 服务，因此选择“custom”选项然后输入必要的信息。</p><p>在第 4 步输入你服务器的公有 IP，运行第 5 步列出的命令，最后点击 “close” 按钮。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run -e CATTLE_AGENT_IP=&quot;192.168.56.2&quot;  --rm --privileged -v /var/run/docker.sock:/var/run/docker.sock -v /var/lib/rancher:/var/lib/rancher rancher/agent:v1.2.11 http://192.168.56.2:8080/v1/scripts/16A52B9BE2BAB87BB0F5:1546214400000:ODACe3sfis5V6U8E3JASL8jQ</span></span>
<span class="line"><span></span></span>
<span class="line"><span>INFO: Running Agent Registration Process, CATTLE_URL=http://192.168.56.2:8080/v1</span></span>
<span class="line"><span>INFO: Attempting to connect to: http://192.168.56.2:8080/v1</span></span>
<span class="line"><span>INFO: http://192.168.56.2:8080/v1 is accessible</span></span>
<span class="line"><span>INFO: Configured Host Registration URL info: CATTLE_URL=http://192.168.56.2:8080/v1 ENV_URL=http://192.168.56.2:8080/v1</span></span>
<span class="line"><span>INFO: Inspecting host capabilities</span></span>
<span class="line"><span>INFO: Boot2Docker: false</span></span>
<span class="line"><span>INFO: Host writable: true</span></span>
<span class="line"><span>INFO: Token: xxxxxxxx</span></span>
<span class="line"><span>INFO: Running registration</span></span>
<span class="line"><span>INFO: Printing Environment</span></span>
<span class="line"><span>INFO: ENV: CATTLE_ACCESS_KEY=9946BD1DCBCFEF3439F8</span></span>
<span class="line"><span>INFO: ENV: CATTLE_AGENT_IP=192.168.56.2</span></span>
<span class="line"><span>INFO: ENV: CATTLE_HOME=/var/lib/cattle</span></span>
<span class="line"><span>INFO: ENV: CATTLE_REGISTRATION_ACCESS_KEY=registrationToken</span></span>
<span class="line"><span>INFO: ENV: CATTLE_REGISTRATION_SECRET_KEY=xxxxxxx</span></span>
<span class="line"><span>INFO: ENV: CATTLE_SECRET_KEY=xxxxxxx</span></span>
<span class="line"><span>INFO: ENV: CATTLE_URL=http://192.168.56.2:8080/v1</span></span>
<span class="line"><span>INFO: ENV: DETECTED_CATTLE_AGENT_IP=172.17.0.1</span></span>
<span class="line"><span>INFO: ENV: RANCHER_AGENT_IMAGE=rancher/agent:v1.2.11</span></span>
<span class="line"><span>INFO: Launched Rancher Agent: e83b22afd0c023dabc62404f3e74abb1fa99b9a178b05b1728186c9bfca71e8d</span></span></code></pre></div><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-5.png" alt=""></p><p>等待几秒钟后新添加的主机将会出现。点击 “Infrastructure &gt;&gt; Hosts” 页面。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-6.png" alt=""></p><h3 id="怎样查看容器" tabindex="-1">怎样查看容器 <a class="header-anchor" href="#怎样查看容器" aria-label="Permalink to “怎样查看容器”">​</a></h3><p>只需要点击下列位置就能列出所有容器。点击 “Infrastructure &gt;&gt; Containers” 页面。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-7.png" alt=""></p><h3 id="怎样创建容器" tabindex="-1">怎样创建容器 <a class="header-anchor" href="#怎样创建容器" aria-label="Permalink to “怎样创建容器”">​</a></h3><p>非常简单，只需点击下列位置就能创建容器。</p><p>点击 “Infrastructure &gt;&gt; Containers &gt;&gt; Add Container” 然后输入每个你需要的信息。为了测试，我将创建一个 <code>latest</code> 标签的 CentOS 容器。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-8.png" alt=""></p><p>在同样的列表位置，点击 “ Infrastructure &gt;&gt; Containers”。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-9.png" alt=""></p><p>点击容器名展示容器的性能信息，如 CPU、内存、网络和存储。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-10.png" alt=""></p><p>选择特定容器，然后点击最右边的“三点”按钮或者点击“Actions”按钮对容器进行管理，如停止、启动、克隆、重启等。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-11.png" alt=""></p><p>如果你想控制台访问容器，只需要点击 “Actions” 按钮中的 “Execute Shell” 选项即可。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-12.png" alt=""></p><h3 id="怎样从应用目录部署容器" tabindex="-1">怎样从应用目录部署容器 <a class="header-anchor" href="#怎样从应用目录部署容器" aria-label="Permalink to “怎样从应用目录部署容器”">​</a></h3><p>Rancher 提供了一个应用模版目录，让部署变的很容易，只需要单击一下就可以。 它维护了多数流行应用，这些应用由 Rancher 社区贡献。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-13.png" alt=""></p><p>点击 “Catalog &gt;&gt; All &gt;&gt; Choose the required application”，最后点击 “Launch” 去部署。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-14.png" alt=""></p><hr>`,61)),e("p",null,[a[10]||(a[10]=n("via: ",-1)),s(t,{href:"https://www.2daygeek.com/rancher-a-complete-container-management-platform-for-production-environment/"},{default:i(()=>[...a[9]||(a[9]=[n("https://www.2daygeek.com/rancher-a-complete-container-management-platform-for-production-environment/",-1)])]),_:1})]),e("p",null,[a[14]||(a[14]=n("作者：",-1)),s(t,{href:"https://www.2daygeek.com/author/magesh/"},{default:i(()=>[...a[11]||(a[11]=[n("Magesh Maruthamuthu",-1)])]),_:1}),a[15]||(a[15]=n(" 译者：",-1)),s(t,{href:"https://github.com/arrowfeng"},{default:i(()=>[...a[12]||(a[12]=[n("arrowfeng",-1)])]),_:1}),a[16]||(a[16]=n(" 校对：",-1)),s(t,{href:"https://github.com/wxy"},{default:i(()=>[...a[13]||(a[13]=[n("wxy",-1)])]),_:1})]),e("p",null,[a[19]||(a[19]=n("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[17]||(a[17]=[n("LCTT",-1)])]),_:1}),a[20]||(a[20]=n(" 原创编译，",-1)),s(t,{href:"https://linux.cn/"},{default:i(()=>[...a[18]||(a[18]=[n("Linux中国",-1)])]),_:1}),a[21]||(a[21]=n(" 荣誉推出",-1))])])}const T=l(d,[["render",h]]);export{x as __pageData,T as default};
